package com.rohit.inventory.controller;
import com.rohit.inventory.dto.response.*; import com.rohit.inventory.service.ReplenishmentService; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/operations") public class OperationsController {private final ReplenishmentService replenishment;public OperationsController(ReplenishmentService replenishment){this.replenishment=replenishment;}@GetMapping("/replenishment-recommendations") @PreAuthorize("hasAuthority('INVENTORY_READ') or hasAuthority('TRANSFER_READ')") public ApiResponse<List<ReplenishmentRecommendationResponse>> recommendations(){return ApiResponse.success("Replenishment recommendations retrieved successfully",replenishment.recommendations());}}
